// BoardServer is the server API for Board service.
// All implementations must embed UnimplementedBoardServer
// for forward compatibility.
type BoardServer interface {
	// Kanban items changed since a cursor (server is the source of truth).
	KanbanPull(context.Context, *KanbanPullRequest) (*KanbanPage, error)
	// Node-side edits. Each item carries the version it was based on; a stale
	// version is returned as a conflict with the server copy.
	KanbanPush(context.Context, *KanbanBatch) (*KanbanPushResult, error)
	// Shared repository memory.
	MemoryPull(context.Context, *MemoryPullRequest) (*MemoryPage, error)
	MemoryPush(context.Context, *MemoryNote) (*MemoryNote, error)
	// Agent-to-agent messages. Refused while the A2A blackout is on.
	A2ASend(context.Context, *A2AEnvelope) (*A2ASendResult, error)
	A2AReceive(*A2AReceiveRequest, grpc.ServerStreamingServer[A2AEnvelope]) error
	// Factory control state (also pushed on Link as FactoryControl).
	State(context.Context, *StateRequest) (*FactoryControl, error)
	// A host asks a person for something (WP-J): identifiers only.
	Attention(context.Context, *AttentionRequest) (*AttentionReceipt, error)
	// Live sessions any node may message, newest first (harnesses.md).
	A2APeers(context.Context, *A2APeersRequest) (*A2APeerList, error)
	// Host schedules (WP-G): the host's scheduled workers, versioned like
	// cards. The owner may edit them in Keleustes; only the host fires them
	// and writes the run record.
	SchedulePull(context.Context, *SchedulePullRequest) (*SchedulePage, error)
	SchedulePush(context.Context, *ScheduleBatch) (*SchedulePushResult, error)
	mustEmbedUnimplementedBoardServer()
}

